antiPatterns.code:
// Avoid: Using Input for paragraphs
<Input placeholder="Enter your story" />

// Prefer: Use Textarea component
<Textarea placeholder="Enter your story" />

// Avoid: No validation feedback
<Input value={invalidValue} />

// Prefer: Show validation state
<Input 
  value={value}
  className={error ? 'border-destructive' : ''}
  aria-invalid={error}
/>

// Avoid: Generic placeholder
<Input placeholder="Text" />

// Prefer: Descriptive placeholder
<Input placeholder="Enter your full name" />
